import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int i = 0, answer = 0;
        // Take the earliest zero-sum triplet, then skip its three positions.
        while (i + 2 < n) {
            if (a[i] + a[i + 1] + a[i + 2] == 0) { answer++; i += 3; }
            else i++;
        }
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)
	a := make([]int, n)
	for i := range a {
		fmt.Scan(&a[i])
	}
	i, answer := 0, 0
	// Take the earliest zero-sum triplet, then skip its three positions.
	for i+2 < n {
		if a[i]+a[i+1]+a[i+2] == 0 {
			answer++
			i += 3
		} else {
			i++
		}
	}
	fmt.Println(answer)
}
